import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"Kernel 日报 2026-11-25","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/25.md","filePath":"notes/kernel-digest/2026/11/25.md"}'),l={name:"notes/kernel-digest/2026/11/25.md"};function n(c,e,i,s,d,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="kernel-日报-2026-11-25" tabindex="-1">Kernel 日报 2026-11-25 <a class="header-anchor" href="#kernel-日报-2026-11-25" aria-label="Permalink to &quot;Kernel 日报 2026-11-25&quot;">​</a></h1><blockquote><p>生成时间：2026-11-25T01:36:36Z｜共 25 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-25 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_1002a5323771-·-linus-torvalds-tell-your-ai-companion-to-get-its-act-together" tabindex="-1"><code>1002a5323771</code> · <a href="https://www.phoronix.com/news/Linus-Torvalds-EXT4-AI-Big" target="_blank" rel="noreferrer">Linus Torvalds: &quot;Tell Your AI Companion To Get Its Act Together&quot;</a> <a class="header-anchor" href="#_1002a5323771-·-linus-torvalds-tell-your-ai-companion-to-get-its-act-together" aria-label="Permalink to &quot;`1002a5323771` · [Linus Torvalds: &quot;Tell Your AI Companion To Get Its Act Together&quot;](https://www.phoronix.com/news/Linus-Torvalds-EXT4-AI-Big)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>一个面向 Linux 7.4-rc5 的 EXT4 pull request 引发 Linus Torvalds 强烈不满：超过 41k 行代码以 &quot;fixes&quot; 名义进入，其中大量是新增 KUnit 测试覆盖以及 AI 生成的 EXT4 补丁。Linus 明确表示不欢迎这种在 rc 阶段塞入大规模新代码的做法，并要求 &quot;Tell Your AI Companion To Get Its Act Together&quot;。</p><blockquote><p><strong>学习价值</strong>：生动展示了内核开发流程中 rc 阶段合并规则与 maintainer 责任的实践案例，也反映了 AI 生成补丁对内核社区规范的冲击。</p></blockquote><h3 id="_6c6c89f0d268-·-patch-rfc-18-19-vfork-wake-up-the-parent-once-the-child-has-left-the-mm" tabindex="-1"><code>6c6c89f0d268</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-18-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 18/19] vfork: wake up the parent once the child has left the mm</a> <a class="header-anchor" href="#_6c6c89f0d268-·-patch-rfc-18-19-vfork-wake-up-the-parent-once-the-child-has-left-the-mm" aria-label="Permalink to &quot;`6c6c89f0d268` · [[PATCH RFC 18/19] vfork: wake up the parent once the child has left the mm](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-18-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>该补丁修正 vfork() 语义：父任务在 mm_release() 中被唤醒的时机本应是子任务完全离开旧 mm 之后，但由于 exec_mmap() 和 exit_mm() 的实现顺序，父任务在子任务仍持有 mm 时就被唤醒。作者追溯了 mm_release() 自 2.2 内核引入以来的历史演变，说明 2.5.56 中 exec 将其移到 mm 切换之前的原因。补丁调整唤醒时机，使 vfork 语义恢复原始设计。</p><blockquote><p><strong>学习价值</strong>：通过这个补丁可以深入理解 vfork/exec/exit 路径中 mm 生命周期管理的历史包袱与锁顺序问题，是学习 mm 子系统演进的好案例。</p></blockquote><h3 id="fcce2aaf3dbb-·-patch-rfc-19-19-selftests-exec-test-when-a-vfork-parent-is-woken-up" tabindex="-1"><code>fcce2aaf3dbb</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-19-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 19/19] selftests/exec: test when a vfork() parent is woken up</a> <a class="header-anchor" href="#fcce2aaf3dbb-·-patch-rfc-19-19-selftests-exec-test-when-a-vfork-parent-is-woken-up" aria-label="Permalink to &quot;`fcce2aaf3dbb` · [[PATCH RFC 19/19] selftests/exec: test when a vfork() parent is woken up](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-19-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>Christian Brauner 提交的 selftests/exec 系列补丁（第 19 个 RFC）测试 vfork() 父任务仅在子任务离开其 mm 后才被唤醒的三种情形：子任务 exec、exec 中途被杀死、以及退出。测试通过让父任务在子任务所在 CPU 上以 realtime 调度类运行并抢占，来捕捉父任务被过早唤醒的竞态，需要内核启用 preemption 且有 realtime 调度类权限。</p><blockquote><p><strong>学习价值</strong>：深入展示 vfork() 与 mm 生命周期的交互语义，以及如何用 realtime 调度类构造竞态窗口编写内核自测试，是学习进程地址空间管理与 selftests 编写技巧的优秀材料。</p></blockquote><h3 id="_869202e8190d-·-patch-rfc-15-19-exec-don-t-take-the-mmap-lock-of-the-old-mm" tabindex="-1"><code>869202e8190d</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-15-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 15/19] exec: don&#39;t take the mmap lock of the old mm</a> <a class="header-anchor" href="#_869202e8190d-·-patch-rfc-15-19-exec-don-t-take-the-mmap-lock-of-the-old-mm" aria-label="Permalink to &quot;`869202e8190d` · [[PATCH RFC 15/19] exec: don&#39;t take the mmap lock of the old mm](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-15-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>该补丁移除 exec_mmap() 在切换到新 mm 时对旧 mm 的 mmap 读锁，该锁历史上仅用于与 coredump 的写锁同步。commit 7e3c4fb7fc19 已将 coredump 检查替换为 mmap_read_lock_killable()，commit 0258b5fd7c71 将 coredump 限制到单个线程组，使旧 mm 的锁保护不再必要。这是 Christian Brauner 系列补丁中简化 exec 路径锁依赖的一环。</p><blockquote><p><strong>学习价值</strong>：结合系列其他补丁，完整展示了 exec 与 coredump 之间锁交互的演进史，对理解 mm 锁层次结构很有价值。</p></blockquote><h3 id="f75b07cb9eb4-·-hid-patches-for-linux-7-4-rc5-bring-ai-fixes-plus-new-hardware" tabindex="-1"><code>f75b07cb9eb4</code> · <a href="https://www.phoronix.com/news/Linux-7.4-rc5-HID" target="_blank" rel="noreferrer">HID Patches For Linux 7.4-rc5 Bring AI Fixes Plus New Hardware</a> <a class="header-anchor" href="#f75b07cb9eb4-·-hid-patches-for-linux-7-4-rc5-bring-ai-fixes-plus-new-hardware" aria-label="Permalink to &quot;`f75b07cb9eb4` · [HID Patches For Linux 7.4-rc5 Bring AI Fixes Plus New Hardware](https://www.phoronix.com/news/Linux-7.4-rc5-HID)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Linux 7.4-rc5 前合入的 HID 子系统更新规模超出预期，原因包括持续的 AI 相关修复、近期补丁评审速度放缓，以及新硬件支持/workaround 的不断涌入。这反映了 rc 阶段子系统维护面临的现实压力。</p><blockquote><p><strong>学习价值</strong>：展示了 HID 子系统在 rc 阶段的合并节奏与 maintainer 面临的补丁评审压力，对理解内核子系统维护流程有参考价值。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（7 条）</li><li><strong>网络</strong>（2 条）</li><li><strong>Rust in Linux</strong>（7 条）</li><li><strong>跟踪与性能</strong>（1 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（7 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="fddfb9d20076-·-collabora-online-sharply-reduces-server-memory-use-with-new-optimization" tabindex="-1"><code>fddfb9d20076</code> · <a href="https://www.phoronix.com/news/Collabora-Online-Half-Memory" target="_blank" rel="noreferrer">Collabora Online Sharply Reduces Server Memory Use With New Optimization</a> <a class="header-anchor" href="#fddfb9d20076-·-collabora-online-sharply-reduces-server-memory-use-with-new-optimization" aria-label="Permalink to &quot;`fddfb9d20076` · [Collabora Online Sharply Reduces Server Memory Use With New Optimization](https://www.phoronix.com/news/Collabora-Online-Half-Memory)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Collabora Online（基于 LibreOffice 的开源网页办公套件）通过优化 copy-on-write 内存处理，将每个文档的内存占用降低了 50%。这是用户态应用的内存优化，并非内核内存管理改动。</p><blockquote><p><strong>学习价值</strong>：copy-on-write 优化思路对理解内存管理概念有启发，但实现位于用户态，与内核 mm 子系统无直接关系。</p></blockquote><h3 id="fcce2aaf3dbb-·-patch-rfc-19-19-selftests-exec-test-when-a-vfork-parent-is-woken-up-1" tabindex="-1"><code>fcce2aaf3dbb</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-19-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 19/19] selftests/exec: test when a vfork() parent is woken up</a> <a class="header-anchor" href="#fcce2aaf3dbb-·-patch-rfc-19-19-selftests-exec-test-when-a-vfork-parent-is-woken-up-1" aria-label="Permalink to &quot;`fcce2aaf3dbb` · [[PATCH RFC 19/19] selftests/exec: test when a vfork() parent is woken up](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-19-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm</em></p><p>Christian Brauner 提交的 selftests/exec 系列补丁（第 19 个 RFC）测试 vfork() 父任务仅在子任务离开其 mm 后才被唤醒的三种情形：子任务 exec、exec 中途被杀死、以及退出。测试通过让父任务在子任务所在 CPU 上以 realtime 调度类运行并抢占，来捕捉父任务被过早唤醒的竞态，需要内核启用 preemption 且有 realtime 调度类权限。</p><blockquote><p><strong>学习价值</strong>：深入展示 vfork() 与 mm 生命周期的交互语义，以及如何用 realtime 调度类构造竞态窗口编写内核自测试，是学习进程地址空间管理与 selftests 编写技巧的优秀材料。</p></blockquote><h3 id="_6c6c89f0d268-·-patch-rfc-18-19-vfork-wake-up-the-parent-once-the-child-has-left-the-mm-1" tabindex="-1"><code>6c6c89f0d268</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-18-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 18/19] vfork: wake up the parent once the child has left the mm</a> <a class="header-anchor" href="#_6c6c89f0d268-·-patch-rfc-18-19-vfork-wake-up-the-parent-once-the-child-has-left-the-mm-1" aria-label="Permalink to &quot;`6c6c89f0d268` · [[PATCH RFC 18/19] vfork: wake up the parent once the child has left the mm](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-18-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm</em></p><p>该补丁修正 vfork() 语义：父任务在 mm_release() 中被唤醒的时机本应是子任务完全离开旧 mm 之后，但由于 exec_mmap() 和 exit_mm() 的实现顺序，父任务在子任务仍持有 mm 时就被唤醒。作者追溯了 mm_release() 自 2.2 内核引入以来的历史演变，说明 2.5.56 中 exec 将其移到 mm 切换之前的原因。补丁调整唤醒时机，使 vfork 语义恢复原始设计。</p><blockquote><p><strong>学习价值</strong>：通过这个补丁可以深入理解 vfork/exec/exit 路径中 mm 生命周期管理的历史包袱与锁顺序问题，是学习 mm 子系统演进的好案例。</p></blockquote><h3 id="c4bd2d978775-·-patch-rfc-17-19-proc-look-up-map-files-vma-without-exec-update-lock-held" tabindex="-1"><code>c4bd2d978775</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-17-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 17/19] proc: look up map_files vma without exec_update_lock held</a> <a class="header-anchor" href="#c4bd2d978775-·-patch-rfc-17-19-proc-look-up-map-files-vma-without-exec-update-lock-held" aria-label="Permalink to &quot;`c4bd2d978775` · [[PATCH RFC 17/19] proc: look up map_files vma without exec_update_lock held](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-17-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm</em></p><p>该补丁优化 /proc/&lt;pid&gt;/map_files 链接解析：自 commit 6255da28d4bb 起，解析 map_files_get_link() 需要持有 exec_update_lock 并等待 mmap lock，导致读取链接的任务会阻塞该任务的 exec 操作。作者指出该锁实际只用于访问检查（ptrace_may_access）和获取检查时的 mm，因此可以缩小锁的持有范围。</p><blockquote><p><strong>学习价值</strong>：展示了 procfs 与 mm 锁交互的细节，帮助学习者理解锁粒度优化如何减少 exec 与 /proc 读取之间的不必要阻塞。</p></blockquote><h3 id="fcbd865469b6-·-patch-rfc-16-19-exit-don-t-take-the-mmap-lock-in-exit-mm" tabindex="-1"><code>fcbd865469b6</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-16-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 16/19] exit: don&#39;t take the mmap lock in exit_mm()</a> <a class="header-anchor" href="#fcbd865469b6-·-patch-rfc-16-19-exit-don-t-take-the-mmap-lock-in-exit-mm" aria-label="Permalink to &quot;`fcbd865469b6` · [[PATCH RFC 16/19] exit: don&#39;t take the mmap lock in exit_mm()](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-16-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm</em></p><p>该补丁移除 exit_mm() 中对 mmap lock 的读锁获取，该锁可追溯到 2003 年，最初用于与 coredump 写锁同步以保护 core_waiters 检查。随着 commit 92307383082d 将检查移入 coredump_task_exit()、commit 0258b5fd7c71 将 core_state 移入 signal_struct，这一锁保护已不再必要。</p><blockquote><p><strong>学习价值</strong>：是学习锁保护需求随代码演进逐渐失效、以及如何通过历史 commit 考证来安全移除遗留锁的绝佳范例。</p></blockquote><h3 id="_869202e8190d-·-patch-rfc-15-19-exec-don-t-take-the-mmap-lock-of-the-old-mm-1" tabindex="-1"><code>869202e8190d</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-15-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 15/19] exec: don&#39;t take the mmap lock of the old mm</a> <a class="header-anchor" href="#_869202e8190d-·-patch-rfc-15-19-exec-don-t-take-the-mmap-lock-of-the-old-mm-1" aria-label="Permalink to &quot;`869202e8190d` · [[PATCH RFC 15/19] exec: don&#39;t take the mmap lock of the old mm](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-15-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm</em></p><p>该补丁移除 exec_mmap() 在切换到新 mm 时对旧 mm 的 mmap 读锁，该锁历史上仅用于与 coredump 的写锁同步。commit 7e3c4fb7fc19 已将 coredump 检查替换为 mmap_read_lock_killable()，commit 0258b5fd7c71 将 coredump 限制到单个线程组，使旧 mm 的锁保护不再必要。这是 Christian Brauner 系列补丁中简化 exec 路径锁依赖的一环。</p><blockquote><p><strong>学习价值</strong>：结合系列其他补丁，完整展示了 exec 与 coredump 之间锁交互的演进史，对理解 mm 锁层次结构很有价值。</p></blockquote><h3 id="e98fa619d2e2-·-patch-rfc-14-19-exec-switch-time-namespace-after-dropping-exec-update-lock" tabindex="-1"><code>e98fa619d2e2</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-14-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 14/19] exec: switch time namespace after dropping exec_update_lock</a> <a class="header-anchor" href="#e98fa619d2e2-·-patch-rfc-14-19-exec-switch-time-namespace-after-dropping-exec-update-lock" aria-label="Permalink to &quot;`e98fa619d2e2` · [[PATCH RFC 14/19] exec: switch time namespace after dropping exec_update_lock](https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-14-e489035395b8@kernel.org/)&quot;">​</a></h3><p><em>Christian Brauner (<a href="mailto:brauner@kernel.org" target="_blank" rel="noreferrer">brauner@kernel.org</a>)｜linux-mm</em></p><p>该补丁将 time namespace 切换移到 exec_update_lock 释放之后执行，因为该切换与凭据变更无关。切换 time namespace 涉及分配新 nsproxy、可能获取 timens offset mutex 和新 mm 的 mmap lock，原先在 exec_update_lock 持有期间执行会扩大锁的持有范围。补丁确保切换仍发生在 vdso 映射之前，并放在 security_bprm_committed_creds() 之后以避免凭据提交后出现失败路径。</p><blockquote><p><strong>学习价值</strong>：演示了 exec 路径中锁顺序与 namespace 切换时机的精细权衡，对学习 exec 生命周期和 time namespace 机制都有帮助。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_4bef146d349b-·-patch-net-next-v3-tg3-avoid-writing-uninitialized-mii-ctrl1000-in-tg3-phy-reset-5703-4-5" tabindex="-1"><code>4bef146d349b</code> · <a href="https://lore.kernel.org/all/20261125004231.1007868-1-irogers@google.com/" target="_blank" rel="noreferrer">[PATCH net-next v3] tg3: Avoid writing uninitialized MII_CTRL1000 in tg3_phy_reset_5703_4_5()</a> <a class="header-anchor" href="#_4bef146d349b-·-patch-net-next-v3-tg3-avoid-writing-uninitialized-mii-ctrl1000-in-tg3-phy-reset-5703-4-5" aria-label="Permalink to &quot;`4bef146d349b` · [[PATCH net-next v3] tg3: Avoid writing uninitialized MII_CTRL1000 in tg3_phy_reset_5703_4_5()](https://lore.kernel.org/all/20261125004231.1007868-1-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜netdev</em></p><p>该补丁修复 tg3 驱动中 tg3_phy_reset_5703_4_5() 的未初始化写入问题：若 MDIO 读取在全部 10 次重试中均失败，phy9_orig 在被写回 MII_CTRL1000 前从未被赋值。补丁引入 phy9_orig_set 标志跟踪读取是否成功，仅在成功时恢复寄存器，同时对 phy9_orig 做零初始化以应对 Clang 的 -Wconditional-uninitialized 检查局限。</p><blockquote><p><strong>学习价值</strong>：一个典型的驱动错误处理路径缺陷修复案例，展示了静态分析工具发现的问题及防御性编程实践。</p></blockquote><h3 id="_1ded4384a840-·-patch-net-v2-octeontx2-af-fix-uninitialized-variables-in-mcs-alloc-handlers" tabindex="-1"><code>1ded4384a840</code> · <a href="https://lore.kernel.org/all/20261125004227.1007723-1-irogers@google.com/" target="_blank" rel="noreferrer">[PATCH net v2] octeontx2-af: Fix uninitialized variables in MCS alloc handlers</a> <a class="header-anchor" href="#_1ded4384a840-·-patch-net-v2-octeontx2-af-fix-uninitialized-variables-in-mcs-alloc-handlers" aria-label="Permalink to &quot;`1ded4384a840` · [[PATCH net v2] octeontx2-af: Fix uninitialized variables in MCS alloc handlers](https://lore.kernel.org/all/20261125004227.1007723-1-irogers@google.com/)&quot;">​</a></h3><p><em>Ian Rogers (<a href="mailto:irogers@google.com" target="_blank" rel="noreferrer">irogers@google.com</a>)｜netdev</em></p><p>该补丁修复 octeontx2-af 驱动中 MCS 资源分配处理函数的未初始化变量问题：rvu_mbox_handler_mcs_alloc_ctrl_pkt_rule() 的 switch 缺少 default 分支，未识别的 rule_type 会导致 &#39;offset&#39; 未初始化；rvu_mbox_handler_mcs_alloc_resources() 中 &#39;rsrc_id&#39; 在特定条件下也会未初始化。补丁对这些非法输入返回 -EINVAL，避免从错误的硬件分区分配规则或误读栈内存。</p><blockquote><p><strong>学习价值</strong>：展示了 mailbox 请求处理中对用户可控输入缺少校验导致未初始化变量使用的典型 bug 模式，对学习驱动输入验证很有参考价值。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="f6fc523da529-·-patch-selftests-bpf-fix-kallsyms-parsing-with-long-rust-symbols" tabindex="-1"><code>f6fc523da529</code> · <a href="https://lore.kernel.org/all/20261124-selftests-bpf-rust_sym-v1-1-32c450d0c4ee@marliere.net/" target="_blank" rel="noreferrer">[PATCH] selftests/bpf: Fix kallsyms parsing with long Rust symbols</a> <a class="header-anchor" href="#f6fc523da529-·-patch-selftests-bpf-fix-kallsyms-parsing-with-long-rust-symbols" aria-label="Permalink to &quot;`f6fc523da529` · [[PATCH] selftests/bpf: Fix kallsyms parsing with long Rust symbols](https://lore.kernel.org/all/20261124-selftests-bpf-rust_sym-v1-1-32c450d0c4ee@marliere.net/)&quot;">​</a></h3><p><em>Ricardo B. Marlière (SUSE) (<a href="mailto:ricardo@marliere.net" target="_blank" rel="noreferrer">ricardo@marliere.net</a>)｜rust-for-linux</em></p><p>该补丁修复 BPF selftests 中 load_kallsyms_local_common() 的解析问题：该函数用 256 字节缓冲读取 /proc/kallsyms，而 commit b8a94bfb3395 将内核符号最大长度提升到 512 后，CONFIG_RUST=y 内核上某些 mangled Rust 符号（如 drm_panic_qr helpers）会溢出缓冲区。fgets() 拆分长行导致后续解析失败，其后的所有符号被静默丢弃，使 ksym_get_addr() 返回错误地址。</p><blockquote><p><strong>学习价值</strong>：揭示了 Rust 长符号名对既有工具链的兼容性冲击，是理解 Rust 集成带来连锁影响的实际案例。</p></blockquote><h3 id="_1c5838cd4240-·-patch-rust-pin-init-document-self-referential-feature" tabindex="-1"><code>1c5838cd4240</code> · <a href="https://lore.kernel.org/all/20261124-dev-pin-init-doc-v1-1-dd0a3eda9018@garyguo.net/" target="_blank" rel="noreferrer">[PATCH] rust: pin-init: document self-referential feature</a> <a class="header-anchor" href="#_1c5838cd4240-·-patch-rust-pin-init-document-self-referential-feature" aria-label="Permalink to &quot;`1c5838cd4240` · [[PATCH] rust: pin-init: document self-referential feature](https://lore.kernel.org/all/20261124-dev-pin-init-doc-v1-1-dd0a3eda9018@garyguo.net/)&quot;">​</a></h3><p><em>Gary Guo (<a href="mailto:gary@kernel.org" target="_blank" rel="noreferrer">gary@kernel.org</a>)｜rust-for-linux</em></p><p>该补丁为 rust/pin-init 的 #[pin_data] 宏文档新增一节，介绍安全创建自引用结构体（self-referential struct）的特性。pin-init 是 Linux Rust 支持中用于安全初始化 pinned 数据的核心基础设施，此次改动在 rust/pin-init/src/lib.rs 中新增 171 行文档。</p><blockquote><p><strong>学习价值</strong>：pin-init 是理解 Rust 内核代码中安全初始化模式的关键模块，该文档补充对学习自引用结构体的安全构造很有帮助。</p></blockquote><h3 id="e214c4254400-·-patch-v2-rust-binder-make-work-items-of-a-deleted-node-a-no-op" tabindex="-1"><code>e214c4254400</code> · <a href="https://lore.kernel.org/all/20261124211809.3692554-1-inguyen@fit.vut.cz/" target="_blank" rel="noreferrer">[PATCH v2] rust_binder: make work items of a deleted node a no-op</a> <a class="header-anchor" href="#e214c4254400-·-patch-v2-rust-binder-make-work-items-of-a-deleted-node-a-no-op" aria-label="Permalink to &quot;`e214c4254400` · [[PATCH v2] rust_binder: make work items of a deleted node a no-op](https://lore.kernel.org/all/20261124211809.3692554-1-inguyen@fit.vut.cz/)&quot;">​</a></h3><p><em>Nguyen Le Duy (<a href="mailto:inguyen@fit.vut.cz" target="_blank" rel="noreferrer">inguyen@fit.vut.cz</a>)｜rust-for-linux</em></p><p>该补丁修复 rust_binder 中已删除节点的 work item 问题：当 Node 的引用归零被从 owner 的 nodes 树中移除后，仍可能有陈旧的 work item 在队列中。若 userspace 随后用相同 ptr 创建了新节点，陈旧 work item 执行 do_work_locked() 时会错误地移除新节点，导致 owner 无法再查找到它。补丁使已删除节点上的 work item 成为 no-op。</p><blockquote><p><strong>学习价值</strong>：展示了异步 work 队列与对象生命周期管理之间的经典竞态问题，对学习 Rust 内核驱动中的并发安全设计很有启发。</p></blockquote><h3 id="_81f2faa0bd10-·-patch-v5-9-9-drm-panthor-add-mali-v15-hardware-support" tabindex="-1"><code>81f2faa0bd10</code> · <a href="https://lore.kernel.org/all/20261124161952.1053586-10-karunika.choo@arm.com/" target="_blank" rel="noreferrer">[PATCH v5 9/9] drm/panthor: Add Mali v15 hardware support</a> <a class="header-anchor" href="#_81f2faa0bd10-·-patch-v5-9-9-drm-panthor-add-mali-v15-hardware-support" aria-label="Permalink to &quot;`81f2faa0bd10` · [[PATCH v5 9/9] drm/panthor: Add Mali v15 hardware support](https://lore.kernel.org/all/20261124161952.1053586-10-karunika.choo@arm.com/)&quot;">​</a></h3><p><em>Karunika Choo (<a href="mailto:karunika.choo@arm.com" target="_blank" rel="noreferrer">karunika.choo@arm.com</a>)｜rust-for-linux</em></p><p>为 drm/panthor 驱动添加 Mali v15 GPU 的硬件描述并接入设备匹配，包括 v15 寄存器映射和产品识别信息。Mali v15 引入了 64 位的 GPU_ID_WIDE 寄存器，其字段布局与早期 GPU 不同，补丁添加了新格式的寄存器定义和解码辅助函数，并在 uAPI 中暴露 gpu_id_wide 字段。</p><blockquote><p><strong>学习价值</strong>：展示了 GPU 驱动如何处理硬件版本差异和 uAPI 演进，是学习 DRM 驱动开发和设备兼容性设计的良好案例。</p></blockquote><h3 id="_907d1aae605b-·-patch-v2-rust-mm-warn-once-on-invalid-vma-range" tabindex="-1"><code>907d1aae605b</code> · <a href="https://lore.kernel.org/all/20261124153228.134723-1-mbkchelofficialdev@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] rust: mm: warn once on invalid VMA range</a> <a class="header-anchor" href="#_907d1aae605b-·-patch-v2-rust-mm-warn-once-on-invalid-vma-range" aria-label="Permalink to &quot;`907d1aae605b` · [[PATCH v2] rust: mm: warn once on invalid VMA range](https://lore.kernel.org/all/20261124153228.134723-1-mbkchelofficialdev@gmail.com/)&quot;">​</a></h3><p><em>Ivan Tverdokhleb (<a href="mailto:mbkchelofficialdev@gmail.com" target="_blank" rel="noreferrer">mbkchelofficialdev@gmail.com</a>)｜rust-for-linux</em></p><p>在 <code>Vma::zap_vma_range()</code> 中使用 <code>debug_assert!()</code> 和 <code>pr_warn_once!()</code> 报告无效的 VMA 范围。v2 版本根据 Miguel 的建议放弃了自定义 <code>warn_once!()</code> 宏及其 KUnit 测试，改用标准机制实现。</p><blockquote><p><strong>学习价值</strong>：演示了 Rust 内核代码中防御性编程与调试断言的惯用写法，以及如何根据维护者反馈精简补丁。</p></blockquote><h3 id="_72782718e7ed-·-patch-rust-binder-reuse-the-thread-lock-in-get-work-local" tabindex="-1"><code>72782718e7ed</code> · <a href="https://lore.kernel.org/all/20261124-perf-binder-local-work-lock-v1-1-bd8de1a840c1@gmail.com/" target="_blank" rel="noreferrer">[PATCH] rust_binder: Reuse the thread lock in get_work_local()</a> <a class="header-anchor" href="#_72782718e7ed-·-patch-rust-binder-reuse-the-thread-lock-in-get-work-local" aria-label="Permalink to &quot;`72782718e7ed` · [[PATCH] rust_binder: Reuse the thread lock in get_work_local()](https://lore.kernel.org/all/20261124-perf-binder-local-work-lock-v1-1-bd8de1a840c1@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>rust_binder 的 <code>get_work_local()</code> 在检查 looper_need_return 标志后释放并重新获取线程锁，补丁改为在标志检查和首次 pop 操作之间保持 guard 不变。阻塞读在条件变量释放 guard 之前注册等待，保证生产者仍能唤醒读者。实测在两台 x86-64 KVM 主机上每次减少 4013 次锁获取和释放。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust guard 对象如何自然地优化锁的持有范围，是理解锁粒度优化与条件变量唤醒时序的实用案例。</p></blockquote><h3 id="_06606cd66383-·-patch-v3-1-1-gpu-nova-core-add-fwctl-driver-for-firmware-control-interface" tabindex="-1"><code>06606cd66383</code> · <a href="https://lore.kernel.org/all/20261124144204.19072-2-alkumar@nvidia.com/" target="_blank" rel="noreferrer">[PATCH v3 1/1] gpu: nova-core: add fwctl driver for firmware control interface</a> <a class="header-anchor" href="#_06606cd66383-·-patch-v3-1-1-gpu-nova-core-add-fwctl-driver-for-firmware-control-interface" aria-label="Permalink to &quot;`06606cd66383` · [[PATCH v3 1/1] gpu: nova-core: add fwctl driver for firmware control interface](https://lore.kernel.org/all/20261124144204.19072-2-alkumar@nvidia.com/)&quot;">​</a></h3><p><em>Alok Kumar (<a href="mailto:alkumar@nvidia.com" target="_blank" rel="noreferrer">alkumar@nvidia.com</a>)｜rust-for-linux</em></p><p>为 nova-core 添加 fwctl 驱动，向用户空间提供向 GSP 发送 GMC API 命令的接口，用户空间只提供命令 ID 和 payload，传输头由内核内部处理。仅允许配置范围内的七个 vGPU 管理命令，拒绝其他所有命令和 scope，并适配 GPU 拥有的命令队列及其 GMC 事务 API。</p><blockquote><p><strong>学习价值</strong>：展示了 fwctl 子系统与 NVIDIA GSP 固件交互的架构，对学习内核与固件通信接口的安全边界设计很有参考价值。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="b3419ea4127c-·-ubuntu-26-10-provides-some-performance-gains-for-intel-panther-lake-on-the-dell-xps-14" tabindex="-1"><code>b3419ea4127c</code> · <a href="https://www.phoronix.com/review/ubuntu-2610-dell-xps-14" target="_blank" rel="noreferrer">Ubuntu 26.10 Provides Some Performance Gains For Intel Panther Lake On The Dell XPS 14</a> <a class="header-anchor" href="#b3419ea4127c-·-ubuntu-26-10-provides-some-performance-gains-for-intel-panther-lake-on-the-dell-xps-14" aria-label="Permalink to &quot;`b3419ea4127c` · [Ubuntu 26.10 Provides Some Performance Gains For Intel Panther Lake On The Dell XPS 14](https://www.phoronix.com/review/ubuntu-2610-dell-xps-14)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>搭载 Intel Core Ultra Series 3 &quot;Panther Lake&quot; 的 Dell XPS 14 预装 Ubuntu 26.04 LTS 出货，升级到 Ubuntu 26.10 可在 Panther Lake 平台上获得额外的 CPU 和 iGPU 性能提升。性能提升主要来自更新的内核与图形驱动栈。</p><blockquote><p><strong>学习价值</strong>：可侧面了解新内核版本对新硬件平台（如 Panther Lake）性能支持的实际收益，但内容偏产品评测。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_1a25c34c1429-·-next-20261124-linux-next" tabindex="-1"><code>1a25c34c1429</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261124-2026-11-24" target="_blank" rel="noreferrer">next-20261124: linux-next</a> <a class="header-anchor" href="#_1a25c34c1429-·-next-20261124-linux-next" aria-label="Permalink to &quot;`1a25c34c1429` · [next-20261124: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261124-2026-11-24)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 24 日发布 next-20261124 版本，作为合并到主线前的集成测试树。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 版本发布有助于学习者了解即将进入主线的补丁动态和内核开发节奏。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_9945a7c48037-·-firefox-161-0-released" tabindex="-1"><code>9945a7c48037</code> · <a href="https://lwn.net/Articles/1109478/" target="_blank" rel="noreferrer">Firefox 161.0 released</a> <a class="header-anchor" href="#_9945a7c48037-·-firefox-161-0-released" aria-label="Permalink to &quot;`9945a7c48037` · [Firefox 161.0 released](https://lwn.net/Articles/1109478/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Firefox 161.0 正式发布，新增为复制当前标签页 URL 分配快捷键、Tab Groups 菜单项，以及按站点开关内置 VPN 的功能，同时包含多项安全修复。这是浏览器层面的版本更新，与内核无关。</p><blockquote><p><strong>学习价值</strong>：对内核学习者价值有限，仅可作为了解用户态软件生态动态的参考。</p></blockquote><h3 id="_6514e933bf87-·-security-updates-for-tuesday" tabindex="-1"><code>6514e933bf87</code> · <a href="https://lwn.net/Articles/1109472/" target="_blank" rel="noreferrer">Security updates for Tuesday</a> <a class="header-anchor" href="#_6514e933bf87-·-security-updates-for-tuesday" aria-label="Permalink to &quot;`6514e933bf87` · [Security updates for Tuesday](https://lwn.net/Articles/1109472/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>AlmaLinux、Debian、Fedora 等发行版发布例行安全更新，涉及 kernel、kernel-rt、openssh、curl 等大量软件包。其中 kernel 相关更新值得发行版用户关注并及时升级。</p><blockquote><p><strong>学习价值</strong>：可留意各发行版 kernel 包的安全公告，了解近期内核漏洞修复的分布情况。</p></blockquote><h3 id="_1002a5323771-·-linus-torvalds-tell-your-ai-companion-to-get-its-act-together-1" tabindex="-1"><code>1002a5323771</code> · <a href="https://www.phoronix.com/news/Linus-Torvalds-EXT4-AI-Big" target="_blank" rel="noreferrer">Linus Torvalds: &quot;Tell Your AI Companion To Get Its Act Together&quot;</a> <a class="header-anchor" href="#_1002a5323771-·-linus-torvalds-tell-your-ai-companion-to-get-its-act-together-1" aria-label="Permalink to &quot;`1002a5323771` · [Linus Torvalds: &quot;Tell Your AI Companion To Get Its Act Together&quot;](https://www.phoronix.com/news/Linus-Torvalds-EXT4-AI-Big)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>一个面向 Linux 7.4-rc5 的 EXT4 pull request 引发 Linus Torvalds 强烈不满：超过 41k 行代码以 &quot;fixes&quot; 名义进入，其中大量是新增 KUnit 测试覆盖以及 AI 生成的 EXT4 补丁。Linus 明确表示不欢迎这种在 rc 阶段塞入大规模新代码的做法，并要求 &quot;Tell Your AI Companion To Get Its Act Together&quot;。</p><blockquote><p><strong>学习价值</strong>：生动展示了内核开发流程中 rc 阶段合并规则与 maintainer 责任的实践案例，也反映了 AI 生成补丁对内核社区规范的冲击。</p></blockquote><h3 id="e0d9097d01d7-·-pop-os-26-04-lts-released-with-more-cosmic-apps-remote-desktop-more" tabindex="-1"><code>e0d9097d01d7</code> · <a href="https://www.phoronix.com/news/Pop-OS-26.04-Released" target="_blank" rel="noreferrer">Pop!_OS 26.04 LTS Released With More COSMIC Apps, Remote Desktop &amp; More</a> <a class="header-anchor" href="#e0d9097d01d7-·-pop-os-26-04-lts-released-with-more-cosmic-apps-remote-desktop-more" aria-label="Permalink to &quot;`e0d9097d01d7` · [Pop!_OS 26.04 LTS Released With More COSMIC Apps, Remote Desktop &amp; More](https://www.phoronix.com/news/Pop-OS-26.04-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>System76 发布 Pop!_OS 26.04 LTS，基于 Ubuntu 26.04 LTS 软件包基础构建，带来更多 COSMIC 桌面应用、远程桌面等新特性。这是发行版层面的发布新闻。</p><blockquote><p><strong>学习价值</strong>：对内核学习无直接价值，仅可了解 Rust 编写的 COSMIC 桌面环境在发行版中的落地进展。</p></blockquote><h3 id="b76ac6663ad6-·-ubuntu-outlines-plans-for-its-ai-powered-new-way-to-interact-with-the-ubuntu-desktop" tabindex="-1"><code>b76ac6663ad6</code> · <a href="https://www.phoronix.com/news/Ubuntu-AI-Desktop-Interact" target="_blank" rel="noreferrer">Ubuntu Outlines Plans For Its AI-Powered New Way To Interact With The Ubuntu Desktop</a> <a class="header-anchor" href="#b76ac6663ad6-·-ubuntu-outlines-plans-for-its-ai-powered-new-way-to-interact-with-the-ubuntu-desktop" aria-label="Permalink to &quot;`b76ac6663ad6` · [Ubuntu Outlines Plans For Its AI-Powered New Way To Interact With The Ubuntu Desktop](https://www.phoronix.com/news/Ubuntu-AI-Desktop-Interact)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Canonical 公布了 Ubuntu 桌面 AI 交互的进一步计划，包括 Ubuntu 26.10 中以 tech preview 形式提供的 Myna 语音转文字功能，以及新设计的 AI 驱动 launcher。这是桌面发行版层面的产品规划新闻。</p><blockquote><p><strong>学习价值</strong>：与内核学习基本无关，仅反映 Linux 桌面生态的 AI 化趋势。</p></blockquote><h3 id="_3ff5ed34150b-·-tornadovm-8-2-released-with-rocm-hip-backend-for-amd-gpus" tabindex="-1"><code>3ff5ed34150b</code> · <a href="https://www.phoronix.com/news/TornadoVM-8.2" target="_blank" rel="noreferrer">TornadoVM 8.2 Released With ROCm HIP Backend For AMD GPUs</a> <a class="header-anchor" href="#_3ff5ed34150b-·-tornadovm-8-2-released-with-rocm-hip-backend-for-amd-gpus" aria-label="Permalink to &quot;`3ff5ed34150b` · [TornadoVM 8.2 Released With ROCm HIP Backend For AMD GPUs](https://www.phoronix.com/news/TornadoVM-8.2)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>TornadoVM 8.2 发布，新增 AMD ROCm HIP 后端，使 Java 代码（OpenJDK 21+）可 JIT 编译到 CUDA、OpenCL C、Apple Metal 和 ROCm HIP 等多种 GPU 目标。这是 Java GPU 编程框架的版本更新。</p><blockquote><p><strong>学习价值</strong>：与内核学习无关，仅涉及 GPU 计算生态动态。</p></blockquote><h3 id="f75b07cb9eb4-·-hid-patches-for-linux-7-4-rc5-bring-ai-fixes-plus-new-hardware-1" tabindex="-1"><code>f75b07cb9eb4</code> · <a href="https://www.phoronix.com/news/Linux-7.4-rc5-HID" target="_blank" rel="noreferrer">HID Patches For Linux 7.4-rc5 Bring AI Fixes Plus New Hardware</a> <a class="header-anchor" href="#f75b07cb9eb4-·-hid-patches-for-linux-7-4-rc5-bring-ai-fixes-plus-new-hardware-1" aria-label="Permalink to &quot;`f75b07cb9eb4` · [HID Patches For Linux 7.4-rc5 Bring AI Fixes Plus New Hardware](https://www.phoronix.com/news/Linux-7.4-rc5-HID)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 7.4-rc5 前合入的 HID 子系统更新规模超出预期，原因包括持续的 AI 相关修复、近期补丁评审速度放缓，以及新硬件支持/workaround 的不断涌入。这反映了 rc 阶段子系统维护面临的现实压力。</p><blockquote><p><strong>学习价值</strong>：展示了 HID 子系统在 rc 阶段的合并节奏与 maintainer 面临的补丁评审压力，对理解内核子系统维护流程有参考价值。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>6c6c89f0d268</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-18-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 18/19] vfork: wake up the parent once the child has left the mm</a></li><li><code>fcce2aaf3dbb</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-19-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 19/19] selftests/exec: test when a vfork() parent is woken up</a></li><li><code>869202e8190d</code> · <a href="https://lore.kernel.org/all/20261124-work-exec-update_lock-v1-15-e489035395b8@kernel.org/" target="_blank" rel="noreferrer">[PATCH RFC 15/19] exec: don&#39;t take the mmap lock of the old mm</a></li></ul>',135)])])}const u=r(l,[["render",n]]);export{m as __pageData,u as default};
